 old,new=values['baseline'],values['candidate'];assert new[:-3]==old;assert [s.split('\t')[1]for s in new[-3:]]==['-filtrosFontes','-filtroTamanhoMax','-filtroGrupos'];assert all(s.split('\t')[2]=='0'for s in new[-3:]);assert int(old[-1].split('\t')[0])+1==len(old);assert all(int(s.split('\t')[0])==len(old)+i for i,s in enumerate(new[-3:]));print(mode,len(old),'existing Settings IDs/keys/defaults/labels preserved;3 appended',flush=True)
